package com.example.Email.Controller;
import com.example.Email.DTO.Request.CompleteEmailOAuthRequest;import com.example.Email.DTO.Response.EmailAccountResponse;import com.example.Email.Entity.EmailProvider;import com.example.Email.Service.EmailAccountService;import com.example.Email.Service.GmailSyncService;import jakarta.validation.Valid;import jakarta.validation.constraints.NotBlank;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/email-accounts") @RequiredArgsConstructor
public class EmailAccountController {private final EmailAccountService service;private final GmailSyncService gmailSync;@GetMapping public List<EmailAccountResponse> list(){return service.list();}@PostMapping("/{provider}/authorization-url") public Map<String,String> authorizationUrl(@PathVariable EmailProvider provider,@RequestParam @NotBlank String redirectUri){return Map.of("authorizationUrl",service.authorizationUrl(provider,redirectUri));}@PostMapping("/oauth/callback") public EmailAccountResponse callback(@Valid @RequestBody CompleteEmailOAuthRequest r){return service.complete(r.code(),r.state());}@PostMapping("/{id}/sync") public Map<String,Integer> sync(@PathVariable Long id){return Map.of("imported",gmailSync.sync(id));}@PostMapping("/sync") public Map<String,Integer> syncAll(){return Map.of("imported",gmailSync.syncConnected());}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void disconnect(@PathVariable Long id){service.disconnect(id);}}
